<style>
.review-page{padding:34px 0 80px}.review-hero{background:linear-gradient(125deg,#103d2a,light-dark(#247a4c, var(--night-brand)));color:#fff;padding:38px;border-radius:24px;margin:18px 0 28px;position:relative;overflow:hidden}.review-hero:after{content:"★";position:absolute;right:35px;top:-50px;font-size:220px;opacity:.08;pointer-events:none}.review-hero h1{color:#fff;font-size:clamp(2rem,4vw,3.1rem);margin:8px 0}.review-hero p{color:#d5f0df;max-width:650px}.review-eyebrow{font-size:.78rem;letter-spacing:.15em;text-transform:uppercase;font-weight:800;color:#b6edca}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:20px}.review-card,.review-form-card,.review-detail{background:light-dark(#fff, var(--night-panel));border:1px solid light-dark(#dce9e0, var(--night-line));border-radius:20px;padding:26px;box-shadow:0 12px 32px light-dark(rgba(14,60,35,.055), var(--night-shadow))}.review-card{display:flex;flex-direction:column;gap:14px}.review-card-top,.review-actions,.review-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.review-avatar{display:grid;place-items:center;background:light-dark(#e3f3e9, var(--night-raised));color:light-dark(#155a37, var(--night-ink));width:46px;height:46px;border-radius:15px;font-size:1.2rem;font-weight:800}.review-author{display:flex;align-items:center;gap:12px}.review-author strong{display:block}.review-author small,.review-muted{color:light-dark(#62796c, var(--night-green))}.review-stars{color:light-dark(#efa927, var(--night-warning-ink));letter-spacing:.1em;font-size:1.3rem}.review-rating{font-weight:800;color:light-dark(#165e39, var(--night-ink))}.review-court{display:inline-flex;align-items:center;gap:6px;color:light-dark(#237447, var(--night-green));font-weight:700}.review-comment{color:light-dark(#304c3b, var(--night-ink));line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}.review-actions{justify-content:flex-start;margin-top:auto;padding-top:12px;border-top:1px solid light-dark(#edf2ee, var(--night-line))}.review-link{color:light-dark(#176a3f, var(--night-green));font-weight:700;text-decoration:none}.review-link:hover{text-decoration:underline}.review-danger{background:light-dark(#fff, var(--night-panel));color:light-dark(#b43c3c, var(--night-danger-ink));border:1px solid light-dark(#f0cbcb, var(--night-line));padding:10px 15px;border-radius:10px;cursor:pointer;font:inherit}.review-danger:hover{background:light-dark(#fff2f2, var(--night-panel))}.review-form-card,.review-detail{max-width:760px;margin:0 auto}.review-label{display:block;margin:22px 0 9px;font-weight:750;color:light-dark(#234b35, var(--night-ink))}.review-textarea{display:block;width:100%;min-height:155px;resize:vertical;padding:16px;border-radius:14px;border:1px solid light-dark(#cbded0, var(--night-line));font:inherit;box-sizing:border-box;background:light-dark(#fbfdfb, var(--night-panel));color:light-dark(#193a29, var(--night-ink))}.review-textarea:focus{outline:3px solid light-dark(#b6e6c8, var(--night-line));border-color:light-dark(#23834e, var(--night-line))}.review-rating-choices{display:flex;gap:8px;flex-wrap:wrap}.review-rating-choices input{position:absolute;opacity:0;width:1px;height:1px}.review-rating-choices label{display:grid;place-items:center;cursor:pointer;font-size:1.8rem;width:53px;height:53px;border:1px solid light-dark(#d7e6dc, var(--night-line));border-radius:13px;color:light-dark(#aab8ae, var(--night-green));background:light-dark(#f7faf8, var(--night-panel));transition:.15s}.review-rating-choices input:checked+label{color:light-dark(#edaa2c, var(--night-warning-ink));background:light-dark(#fff7e5, var(--night-warning-bg));border-color:light-dark(#edaa2c, var(--night-line))}.review-rating-choices input:focus-visible+label{outline:3px solid light-dark(#66bb85, var(--night-line))}.review-rating-choices label:hover{transform:translateY(-2px);color:light-dark(#edaa2c, var(--night-warning-ink))}.review-submit{border:0;background:#176b40;color:white;padding:13px 24px;border-radius:12px;font:inherit;font-weight:750;cursor:pointer}.review-submit:hover{background:#10532f}.review-form-actions{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin-top:24px}.review-alert{padding:14px 18px;border-radius:12px;margin:18px 0;background:light-dark(#e8f7ed, var(--night-raised));color:light-dark(#155d36, var(--night-ink))}.review-alert.error{background:light-dark(#fff1f1, var(--night-panel));color:light-dark(#9d3030, var(--night-danger-ink))}.review-alert ul{margin:8px 0 0}.review-empty{text-align:center;padding:65px 25px;border:1px dashed light-dark(#bfd6c5, var(--night-line));border-radius:20px;background:light-dark(#f8fcf9, var(--night-panel))}.review-empty-icon{font-size:3rem;color:light-dark(#edaa2c, var(--night-warning-ink))}.review-pagination{margin-top:28px}.review-detail .review-comment{font-size:1.08rem}.review-divider{height:1px;background:light-dark(#e4eee7, var(--night-raised));margin:22px 0}.review-booking-pill{display:inline-block;background:light-dark(#e5f3e9, var(--night-raised));border-radius:100px;padding:8px 14px;color:light-dark(#175e37, var(--night-ink));font-weight:750}.review-back{display:inline-block;margin-bottom:16px}.review-note{font-size:.9rem;color:light-dark(#657c6c, var(--night-green));margin-top:7px}@media(max-width:600px){.review-hero{padding:27px 22px}.review-card,.review-form-card,.review-detail{padding:20px}.review-rating-choices label{width:45px;height:48px}}
</style>